 * Serializes a request body for use in a Swagger "try it out" request.
 *
 * Swagger UI hands us the same body value it would pass to `fetch`, which may be
 * a string, URLSearchParams, FormData, Blob/File, or (typed) binary data. Bruno's
 * proxy can only forward text-based bodies, so anything binary or multipart is
 * rejected here with a descriptive TypeError.
 */

export const UNSUPPORTED_BODY_TYPE_CODE = 'UNSUPPORTED_BODY_TYPE';

/**
 * Builds a human-readable message explaining that a given body type isn't
 * supported and which alternatives are.
 */
export const UNSUPPORTED_BODY_MESSAGE = (bodyTypeName) =>
  `${bodyTypeName} isn't supported in Bruno yet. Supported request body types are JSON, URL-encoded forms, plain text.`;

const unsupportedBodyError = (message, bodyType) => {
  const error = new TypeError(message);
  error.code = UNSUPPORTED_BODY_TYPE_CODE;
  error.bodyType = bodyType;
  return error;
};

export const serializeBody = (body) => {
  if (body === null || body === undefined) {
    return undefined;
  }

  if (typeof body === 'string') {
    return body;
  }

  if (typeof URLSearchParams !== 'undefined' && body instanceof URLSearchParams) {
    return body.toString();
  }

  if (typeof FormData !== 'undefined' && body instanceof FormData) {
    throw unsupportedBodyError(
      `${UNSUPPORTED_BODY_MESSAGE('Multipart form data')} Create a Bruno request to send multipart form data.`,
      'FormData'
    );
  }

  // File extends Blob, so it must be checked first.
  if (typeof File !== 'undefined' && body instanceof File) {
    throw unsupportedBodyError(UNSUPPORTED_BODY_MESSAGE('File upload'), 'File');
  }

  if (typeof Blob !== 'undefined' && body instanceof Blob) {
    throw unsupportedBodyError(UNSUPPORTED_BODY_MESSAGE('Binary file upload'), 'Blob');
  }

  if (body instanceof ArrayBuffer) {
    throw unsupportedBodyError(UNSUPPORTED_BODY_MESSAGE('Binary data'), 'ArrayBuffer');
  }

  if (ArrayBuffer.isView(body)) {
    throw unsupportedBodyError(UNSUPPORTED_BODY_MESSAGE('Binary data'), body.constructor?.name || 'TypedArray');
  }

  return body;
};

export default serializeBody;
